local uihelper = require(script.Parent.UIHelper)
local bindablefunc: BindableFunction = script.Parent.Parent.BindableFunction
local module = {}
module.__index = module

function module.new(vm, v)
	local self = {}
	local mt = {
		_openCallbacks = nil,
		_closeCallbacks = nil,

		_name = v,
		_belong = vm,
		_opening = false,

		_view = nil,
		_content = nil,

		_getVMS = function(self, vm)
			local vms = bindablefunc:Invoke("_getViewModelScript", vm)
			return vms
		end,
		_getView = function(self)
			if self._view then
				return self._view
			end
			local vms = self:_getVMS(vm)
			if vms then
				if vms:FindFirstChild("View") and vms.View:FindFirstChild(v) then
					self._view = require(vms.View[v])
					return self._view
				end
			end
		end,
		_getContent = function(self)
			if self._content then
				return self._content
			end
			local view = self:_getView()
			if view then
				local content = view:GetContent()
				self._content = content
				return self._content
			end
		end,

		_getOpenCallbacks = function(self)
			if not self._openCallbacks then
				self._openCallbacks = {}
				local vms = vm and bindablefunc:Invoke("_getViewModelScript", vm)
				if not vms then
					vms = self._view.DataContext and self._view.DataContext._script
				end
				if vms then
					local vm = require(vms)
					if vm["OnOpen"] then
						table.insert(self._openCallbacks, function(...)
							vm["OnOpen"](vm, ...)
						end)
					end
					if vms:FindFirstChild("View") then
						for i, v in pairs(vms.View:GetDescendants()) do
							if not v:IsA("ModuleScript") then
								continue
							end
							local view = require(v)
							if view["OnOpen"] then
								table.insert(self._openCallbacks, function(...)
									view["OnOpen"](view, ...)
								end)
							end
						end
					end
				else
					if self._view.OnOpen then
						table.insert(self._openCallbacks, function(...)
							self._view.OnOpen(self._view, ...)
						end)
					end
				end
			end

			return self._openCallbacks
		end,

		_getCloseCallbacks = function(self)
			if not self._closeCallbacks then
				self._closeCallbacks = {}
				local vms = vm and bindablefunc:Invoke("_getViewModelScript", vm)
				if not vms then
					vms = self._view.DataContext and self._view.DataContext._script
				end
				if vms then
					local vm = require(vms)
					if vm["OnClose"] then
						table.insert(self._closeCallbacks, function(...)
							vm["OnClose"](vm, ...)
						end)
					end
					if vms:FindFirstChild("View") then
						for i, v in pairs(vms.View:GetDescendants()) do
							if not v:IsA("ModuleScript") then
								continue
							end
							local view = require(v)
							if view["OnClose"] then
								table.insert(self._closeCallbacks, function(...)
									view["OnClose"](view, ...)
								end)
							end
						end
					end
				else
					if self._view.OnClose then
						table.insert(self._closeCallbacks, function(...)
							self._view.OnClose(self._view, ...)
						end)
					end
				end
			end

			return self._closeCallbacks
		end,
	}

	for i, v in pairs(module) do
		mt[i] = v
	end

	setmetatable(self, {
		__index = function(t, k)
			if mt[k] ~= nil then
				return mt[k]
			end
			local value = rawget(t, k)
			return value
		end,
	})

	return self
end

function module:Open(...)
	if self._opening then
		return false
	end
	local args = { ... }
	local view = self:_getView()
	if view and view["GetContent"] then
		local content = view:GetContent()
		if content then
			self._opening = true
			local _, animator = view:HasComponent(content, "Animator")
			if animator and animator._transitionIn then
				animator:TransitionIn()
			else
				uihelper:Open(content)
			end
			local _openCallbacks = self:_getOpenCallbacks()
			for i, v in pairs(_openCallbacks) do
				spawn(function()
					local suc, err = pcall(v, table.unpack(args))
					if not suc then
						warn(err)
						warn(debug.traceback())
					end
				end)
			end
			return true
		else
			warn(`[NezaUI] Window:Open: ${self._name} not found content`)
		end
	else
		warn(`[NezaUI] Window:Open: ${self._name} not found view`)
	end
end

function module:Close(...)
	if not self._opening then
		return false
	end
	local args = { ... }
	local view = self:_getView()
	if view and view["GetContent"] then
		local content = view:GetContent()
		if content then
			self._opening = false
			local _, animator = view:HasComponent(content, "Animator")
			if animator and animator._transitionOut then
				animator:TransitionOut()
			else
				uihelper:Close(content)
			end
			local _closeCallbacks = self:_getCloseCallbacks()
			for i, v in pairs(_closeCallbacks) do
				spawn(function()
					local suc, err = pcall(v, table.unpack(args))
					if not suc then
						warn(err)
						warn(debug.traceback())
					end
				end)
			end
			return true
		else
			warn(`[NezaUI] Window:Close: ${self._name} not found content`)
		end
	else
		warn(`[NezaUI] Window:Close: ${self._name} not found view`)
	end
end

return module
